observation.query:
SELECT DISTINCT ?graph ?subject ?predicate ?object
WHERE {
  VALUES ?graph {
    <urn:graphragprov:unit:u_6e78307007f810fd>
    <urn:graphragprov:unit:u_7aaee90dcc3389c8>
    <urn:graphragprov:unit:u_ea7aa27fc1e849a3>
  }
  GRAPH ?graph {
    ?subject ?predicate ?object .
    FILTER(isIRI(?subject))
  }
}
ORDER BY ?graph ?subject ?predicate ?object
